#!/usr/bin/env bash
# Live DAP verification for the built-in gdb adapter.
#
# Gate 1 is the preflight: gdb must be DAP-capable (Python + dap
# interpreter). On a host without it the script exits non-zero here, which is
# what CI asserts on such hosts (see scripts/verify-dap.expected.md).
#
# Past the gate, the script exercises real DAP behavior through
# verify-dap-client.mjs: a launch with the printers `-iex` mechanism, a
# core-file attach, and a live-PID attach (the `pid` field the provider maps
# `processId` to). The core file is generated by gdb itself so no kernel
# core_pattern configuration is needed.
set -euo pipefail

GDB="${GDB:-gdb}"
CC="${CC:-cc}"

# Preflight: gdb must be DAP-capable (Python + dap interpreter).
if ! command -v "$GDB" >/dev/null 2>&1; then
  echo "gdb not found on PATH"
  exit 1
fi

if ! command -v "$CC" >/dev/null 2>&1; then
  echo "no C compiler ($CC) to build DAP fixtures"
  exit 1
fi

python_out="$("$GDB" --batch -ex 'python print("ok")' 2>&1 || true)"
dap_out="$("$GDB" -i=dap --batch </dev/null 2>&1 || true)"

if echo "$python_out" | grep -q "Python scripting is not supported"; then
  ver="$("$GDB" --version 2>&1 | head -1 | grep -oE '[0-9]+\.[0-9]+' | head -1)"
  echo "gdb ${ver} has no DAP support (built without Python). Install gdb >= 13 with Python, or enable the cppdbg fallback (v.debug.adapter = 'cppdbg')."
  exit 1
fi
if echo "$dap_out" | grep -qi "unrecognized\|Could not find interpreter"; then
  ver="$("$GDB" --version 2>&1 | head -1 | grep -oE '[0-9]+\.[0-9]+' | head -1)"
  echo "gdb ${ver} has no DAP support (built without Python). Install gdb >= 13 with Python, or enable the cppdbg fallback (v.debug.adapter = 'cppdbg')."
  exit 1
fi

echo "Preflight passed: gdb is DAP-capable."

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
WORK="$(mktemp -d)"
VICTIM_PID=""
cleanup() {
  if [ -n "${VICTIM_PID}" ]; then
    kill "${VICTIM_PID}" 2>/dev/null || true
  fi
  rm -rf "${WORK}"
}
trap cleanup EXIT

# Fixtures: a hello-world for launch and a crasher for the core file.
cat > "${WORK}/hello.c" <<'EOF'
#include <stdio.h>
int main(void) { printf("v-dap-hello\n"); return 0; }
EOF
cat > "${WORK}/crasher.c" <<'EOF'
#include <signal.h>
static void crash(void) { raise(SIGSEGV); }
int main(void) { crash(); return 0; }
EOF
"$CC" -g -o "${WORK}/hello" "${WORK}/hello.c"
"$CC" -g -o "${WORK}/crasher" "${WORK}/crasher.c"

# Printers load check outside DAP: sourcing must not error.
if ! printers_out="$("$GDB" --batch -ex "source ${ROOT}/scripts/gdb/v_printers.py" -ex quit 2>&1)"; then
  echo "FAIL: pretty printers: source failed:"
  echo "${printers_out}" | head -20
  exit 1
fi
if echo "${printers_out}" | grep -qi "Traceback\|Error in sourced command"; then
  echo "FAIL: pretty printers: source errors:"
  echo "${printers_out}" | head -20
  exit 1
fi
echo "PASS: pretty printers (batch source)"

# Core file via gdb itself: deterministic, no core_pattern dependency.
(cd "${WORK}" && "$GDB" --batch -ex run -ex "generate-core-file ${WORK}/core.test" -ex kill ./crasher >/dev/null 2>&1 || true)
if [ ! -f "${WORK}/core.test" ]; then
  echo "FAIL: core-file attach: gdb did not generate ${WORK}/core.test"
  exit 1
fi

# Live target for PID attach (what the provider's pid mapping feeds).
# The victim opts out of Yama scope 1 via PR_SET_PTRACER_ANY, so gdb may
# attach to it even though it is not gdb's child — stock Ubuntu confines
# ptrace to descendants otherwise.
cat > "${WORK}/victim.c" <<'EOF'
#include <sys/prctl.h>
#include <unistd.h>
#ifndef PR_SET_PTRACER_ANY
#define PR_SET_PTRACER_ANY ((unsigned long)-1)
#endif
int main(void) {
  prctl(PR_SET_PTRACER, PR_SET_PTRACER_ANY, 0, 0, 0);
  for (;;) pause();
  return 0;
}
EOF
"$CC" -g -o "${WORK}/victim" "${WORK}/victim.c"
"${WORK}/victim" &
VICTIM_PID=$!

# The client bounds every request internally; `timeout` (where available)
# caps the whole step so a wedged adapter fails loudly instead of hanging CI.
if command -v timeout >/dev/null 2>&1; then
  timeout 300 node "${ROOT}/scripts/verify-dap-client.mjs" \
    --gdb="$GDB" \
    --printers="${ROOT}/scripts/gdb/v_printers.py" \
    --work="$WORK" \
    --attach-bin="${WORK}/victim" \
    --attach-pid="$VICTIM_PID"
else
  node "${ROOT}/scripts/verify-dap-client.mjs" \
    --gdb="$GDB" \
    --printers="${ROOT}/scripts/gdb/v_printers.py" \
    --work="$WORK" \
    --attach-bin="${WORK}/victim" \
    --attach-pid="$VICTIM_PID"
fi

echo "PASS: verify-dap"
